21	// Free bytes on the filesystem holding `dir`, or -1 if it does not exist.
22	long long free_bytes(const std::string& dir) {
23	  struct statvfs vfs;
24	  if (statvfs(dir.c_str(), &vfs) != 0) return -1;
25	  return static_cast<long long>(vfs.f_bavail) *
26	         static_cast<long long>(vfs.f_frsize);
27	}
