97	std::vector<std::string> wsl_warnings(const std::string& proc_version,
98	                                      const std::string& repo_dir,
99	                                      const std::vector<MmapTier>& tiers) {
100	  std::string lower = proc_version;
101	  for (char& c : lower) c = static_cast<char>(std::tolower(
102	      static_cast<unsigned char>(c)));
103	  if (lower.find("microsoft") == std::string::npos) return {};
104	
105	  std::vector<std::string> warns;
106	  warns.push_back(
107	      "WSL2: /dev/shm is capped by the WSL VM memory; raise memory= in "
108	      ".wslconfig if tier 1 is too small");
109	  if (repo_dir.starts_with("/mnt/"))
110	    warns.push_back("repo is under /mnt/ (drvfs): slow, and MAP_SHARED is "
111	                    "not coherent -- keep the repo in the Linux home (~)");
112	  for (const MmapTier& t : tiers)
113	    if (t.dir.starts_with("/mnt/"))
114	      warns.push_back("mmap dir " + t.dir +
115	                      " is under /mnt/ (drvfs): MAP_SHARED is not coherent "
116	                      "there -- use a Linux-side dir");
117	  return warns;
118	}
