120	std::vector<std::string> qemu_m_args(const std::string& spec,
121	                                     std::string& err) {
122	  err.clear();
123	  if (spec.empty()) return {};
124	  const long long bytes = parse_size(spec, err);
125	  if (!err.empty()) {
126	    err = "--mem-size: " + err;
127	    return {};
128	  }
129	  if (bytes % (1024 * 1024) != 0) {
130	    err = "--mem-size '" + spec +
131	          "': QEMU's -m takes whole MiB; round to a multiple of 1M";
132	    return {};
133	  }
134	  return {"-m", std::to_string(bytes / (1024 * 1024)) + "M"};
135	}
