164	std::string andesim_cache_dir() {
165	  if (const char* xdg = std::getenv("XDG_CACHE_HOME"); xdg && xdg[0])
166	    return std::string(xdg) + "/andesim";
167	  if (const char* home = std::getenv("HOME"); home && home[0])
168	    return std::string(home) + "/.cache/andesim";
169	  return "";
170	}
