172	std::vector<MmapTier> mmap_tiers() {
173	  if (const char* pinned = std::getenv("HSIM_MMAP_DIR"); pinned && pinned[0])
174	    return {{pinned, "HSIM_MMAP_DIR='" + std::string(pinned) + "'"}};
175	
176	  const std::string cache = andesim_cache_dir();
177	
178	  std::vector<MmapTier> tiers = {{"/dev/shm", "/dev/shm"}};
179	  if (!cache.empty()) {
180	    std::error_code ec;
181	    std::filesystem::create_directories(cache, ec);  // probe needs it to exist
182	    tiers.push_back({cache, cache});
183	  }
184	  return tiers;
185	}
